var script$1$ = {
	name: 'CnPollPicker',

	components: { NcButton: vue.NcButton, NcDialog: vue.NcDialog, NcEmptyContent: vue.NcEmptyContent, NcLoadingIcon: vue.NcLoadingIcon, NcNoteCard: vue.NcNoteCard, NcTextField: vue.NcTextField, Poll },

	props: {
		/** Base API URL for OR. */
		apiBase: { type: String, default: '/apps/openregister/api' },
		/** Pre-translated dialog title. */
		dialogTitle: { type: String, default: () => l10n.translate('nextcloud-vue', 'Link an existing poll') },
	},

	emits: ['close', 'link'],

	data() {
		return {
			loading: false,
			error: '',
			polls: [],
			search: '',
			selectedPollId: null,
			searchTimer: null,
		}
	},

	computed: {
		/**
		 * Client-side filter on top of the server-side `?search=`
		 * payload — so the user sees instant feedback even between
		 * debounce ticks.
		 *
		 * @return {Array}
		 */
		visiblePolls() {
			const term = this.search.trim().toLowerCase();
			if (term === '') {
				return this.polls
			}
			return this.polls.filter(poll => (poll.title || '').toLowerCase().includes(term))
		},
	},

	mounted() {
		this.fetchPolls();
	},

	beforeDestroy() {
		if (this.searchTimer) {
			clearTimeout(this.searchTimer);
		}
	},

	methods: {
		t: l10n.translate,

		/**
		 * Dismiss the dialog.
		 *
		 * @return {void}
		 */
		onClose() {
			/**
			 * @event close Emitted when the dialog should be closed (cancel or close button).
			 */
			this.$emit('close');
		},

		async fetchPolls(searchTerm = '') {
			this.loading = true;
			this.error = '';
			try {
				const query = searchTerm ? `?search=${encodeURIComponent(searchTerm)}` : '';
				const response = await fetch(`${this.apiBase}/integrations/polls/available${query}`, {
					headers: buildHeaders(),
				});
				if (response.ok) {
					const data = await response.json();
					this.polls = data.results || [];
				} else if (response.status === 501) {
					this.error = l10n.translate('nextcloud-vue', 'NC Polls is not installed.');
				} else {
					this.error = l10n.translate('nextcloud-vue', 'Could not load polls.');
				}
			} catch (err) {
				// eslint-disable-next-line no-console
				console.error('[CnPollPicker] fetch polls failed', err);
				this.error = l10n.translate('nextcloud-vue', 'Could not load polls.');
			} finally {
				this.loading = false;
			}
		},

		onSearch(value) {
			// Debounce server-side filter; client-side filter is live.
			this.search = value;
			if (this.searchTimer) {
				clearTimeout(this.searchTimer);
			}
			this.searchTimer = setTimeout(() => {
				this.fetchPolls(this.search.trim());
			}, 300);
		},

		pickPoll(poll) {
			this.selectedPollId = poll.id;
		},

		rowMeta(poll) {
			const parts = [];
			const type = poll.type || '';
			if (type !== '') {
				parts.push(type);
			}
			const optionCount = Number(poll.optionCount || 0);
			if (optionCount > 0) {
				parts.push(l10n.translate('nextcloud-vue', '{n} options', { n: optionCount }));
			}
			const voterCount = Number(poll.voterCount || 0);
			if (voterCount > 0) {
				parts.push(l10n.translate('nextcloud-vue', '{n} voters', { n: voterCount }));
			}
			if (poll.closed === true) {
				parts.push(l10n.translate('nextcloud-vue', 'Closed'));
			}
			return parts.join(' · ')
		},

		confirm() {
			if (!this.selectedPollId) {
				return
			}
			/**
			 * @event link Emitted when the user confirms the selection. Payload: `{ pollId }`.
			 */
			this.$emit('link', { pollId: this.selectedPollId });
		},
	},
};

