// tryOnScopeDispose is from @vueuse/core — available as peerDependency
let _tryOnScopeDispose = null;
try {
	// Dynamic import guard: avoid hard failure if @vueuse/core is absent
	const vueuse = require('@vueuse/core');
	_tryOnScopeDispose = vueuse.tryOnScopeDispose;
} catch {
	// @vueuse/core not installed — auto-cleanup unavailable; manual unsubscribe required
}

/**
 * Compute a stable cache key for dedup of fetchCollection calls.
 *
 * @param {string} type Object type slug
 * @param {object} params Query params
 * @return {string}
 */
function collectionDedupKey(type, params) {
	return `${type}:${JSON.stringify(params)}`
}

/**
 * Compute the cache key for dedup of fetchObject calls.
 *
 * @param {string} type Object type slug
 * @param {string} id Object ID
 * @return {string}
 */
function objectDedupKey(type, id) {
	return `${type}:${id}`
}

function liveUpdatesPlugin(opts = {}) {
	const pluginPollCollection = opts.pollIntervalCollection || 30000;
	const pluginPollObject = opts.pollIntervalObject || 60000;

	return {
		name: 'liveUpdates',

		state: () => ({
			/** @type {'offline'|'connecting'|'live'|'reconnecting'|'polling'} */
			liveStatus: 'offline',
			/** @type {number} */
			liveSubscriptions: 0,
			/** @type {Date|null} */
			liveLastEventAt: null,
		}),

		getters: {
			/**
			 * Get the current transport status.
			 *
			 * @param {object} state
			 * @return {string}
			 */
			getLiveStatus: (state) => state.liveStatus,

			/**
			 * Get the number of active subscriptions.
			 *
			 * @param {object} state
			 * @return {number}
			 */
			getLiveSubscriptions: (state) => state.liveSubscriptions,

			/**
			 * Get the timestamp of the last received live event.
			 *
			 * @param {object} state
			 * @return {Date|null}
			 */
			getLiveLastEventAt: (state) => state.liveLastEventAt,
		},

		actions: {
			/**
			 * Subscribe to live updates for an object type.
			 *
			 * When `id` is provided: subscribes to `or-object-{id}` (per-object events).
			 * When `id` is omitted: subscribes to `or-collection-{registerSlug}-{schemaSlug}`
			 *   derived from objectTypeRegistry. Slugs are lazy-fetched if not already cached.
			 *
			 * **Options API note**: In `mounted()` without an active Vue scope,
			 * `tryOnScopeDispose` cannot auto-register cleanup. Call `unsubscribe(handle)`
			 * manually in `beforeDestroy`.
			 *
			 * @param {string} type Registered object type slug
			 * @param {string} [id] Object UUID (omit for collection subscription)
			 * @param {object} [subscribeOpts] Options
			 * @param {number} [subscribeOpts.interval] Override poll interval (ms)
			 * @return {Promise<object>} Opaque handle for unsubscribe()
			 * @throws {Error} If type is not registered, or if lazy slug fetch fails (collection form)
			 */
			async subscribe(type, id, subscribeOpts = {}) {
				const config = this.objectTypeRegistry[type];
				if (!config) {
					throw new Error(`"${type}" is not registered. Call registerObjectType('${type}', ...) first.`)
				}

				const liveUpdates = getLiveUpdates({
					pollIntervalCollection: pluginPollCollection,
					pollIntervalObject: pluginPollObject,
				});

				// Register transport status observer (idempotent: only once per store instance)
				if (!this.__liveStatusObserverRegistered) {
					this.__liveStatusObserverRegistered = true;
					liveUpdates.onStatusChange((newStatus) => {
						this.liveStatus = { ...this.liveStatus, valueOf: undefined, toString: undefined };
						// Vue 2 spread pattern for primitive reactive update
						this.liveStatus = newStatus;
					});
				}

				let eventKey;
				let isObject = false;

				if (id !== undefined && id !== null) {
					// Object subscription — no slug lookup needed
					isObject = true;
					eventKey = buildObjectKey(id);
				} else {
					// Collection subscription — need registerSlug + schemaSlug
					let { registerSlug, schemaSlug } = config;

					if (!registerSlug || !schemaSlug) {
						// Lazy fetch slugs via existing store actions
						try {
							const [register, schema] = await Promise.all([
								this.fetchRegister(type),
								this.fetchSchema(type),
							]);

							if (!register || !register.slug) {
								throw new Error(`Failed to resolve register slug for "${type}"`)
							}
							if (!schema || !schema.slug) {
								throw new Error(`Failed to resolve schema slug for "${type}"`)
							}

							registerSlug = register.slug;
							schemaSlug = schema.slug;

							// Cache slugs in registry (Vue 2 spread pattern)
							this.objectTypeRegistry = {
								...this.objectTypeRegistry,
								[type]: { ...config, registerSlug, schemaSlug },
							};
						} catch (err) {
							throw new Error(`liveUpdatesPlugin: cannot subscribe to "${type}" collection — ${err.message}`)
						}
					}

					eventKey = buildCollectionKey(registerSlug, schemaSlug);
				}

				// Set status to 'connecting' on first subscribe (before transport sets it)
				if (this.liveStatus === 'offline') {
					this.liveStatus = 'connecting';
				}

				const store = this;

				const callback = isObject
					? () => {
						store.liveLastEventAt = new Date();
						// Dispatch fetchObject with dedup
						store.fetchObject(type, id);
					}
					: () => {
						store.liveLastEventAt = new Date();
						// Dispatch fetchCollection with last stashed params + dedup
						const lastParams = store.__lastCollectionParams?.get(type) || {};
						store.fetchCollection(type, lastParams);
					};

				const transportOpts = {
					isObject,
					interval: subscribeOpts.interval || (isObject ? pluginPollObject : pluginPollCollection),
				};

				const transportHandle = liveUpdates.subscribe(eventKey, callback, transportOpts);

				// Update reactive subscriptions count (Vue 2 spread)
				this.liveSubscriptions = this.liveSubscriptions + 1;

				// Update liveStatus from transport now that we've subscribed
				const transportStatus = liveUpdates.getStatus();
				if (transportStatus !== 'offline') {
					this.liveStatus = transportStatus;
				}

				const handle = {
					_livePlugin: true,
					type,
					id,
					eventKey,
					transportHandle,
				};

				// Auto-cleanup via tryOnScopeDispose (Vue 2.7 composition API scopes)
				if (_tryOnScopeDispose) {
					try {
						_tryOnScopeDispose(() => {
							this.unsubscribe(handle);
						});
					} catch {
						// Not in a scope — manual unsubscribe required in beforeDestroy
					}
				}

				return handle
			},

			/**
			 * Unsubscribe from live updates.
			 *
			 * @param {object} handle Handle returned by subscribe()
			 */
			unsubscribe(handle) {
				if (!handle || !handle._livePlugin) return

				const liveUpdates = getLiveUpdates();
				liveUpdates.unsubscribe(handle.transportHandle);

				this.liveSubscriptions = Math.max(0, this.liveSubscriptions - 1);
			},
		},

		/**
		 * Plugin setup hook — called once per store instance.
		 * Sets up:
		 * 1. `$onAction` observer for fetchCollection → stash last params
		 * 2. In-flight dedup Maps for fetchObject and fetchCollection
		 *
		 * @param {object} store The Pinia store instance
		 */
		setup(store) {
			// -- Last-params stash for collection re-fetch on events --
			// Plain (non-reactive) Map: type → last params object
			store.__lastCollectionParams = new Map();

			store.$onAction(({ name, args, after }) => {
				if (name === 'fetchCollection') {
					const [type, params = {}] = args;
					after(() => {
						store.__lastCollectionParams.set(type, params);
					});
				}
			});

			// -- In-flight dedup for fetchObject --
			// Plain Map: dedupKey → Promise
			const objectInFlight = new Map();

			const originalFetchObject = store.fetchObject.bind(store);
			store.fetchObject = async function dedupedFetchObject(type, id) {
				const key = objectDedupKey(type, id);
				if (objectInFlight.has(key)) {
					return objectInFlight.get(key)
				}
				const promise = originalFetchObject(type, id).finally(() => {
					objectInFlight.delete(key);
				});
				objectInFlight.set(key, promise);
				return promise
			};

			// -- In-flight dedup for fetchCollection --
			const collectionInFlight = new Map();

			const originalFetchCollection = store.fetchCollection.bind(store);
			store.fetchCollection = async function dedupedFetchCollection(type, params = {}) {
				const key = collectionDedupKey(type, params);
				if (collectionInFlight.has(key)) {
					return collectionInFlight.get(key)
				}
				const promise = originalFetchCollection(type, params).finally(() => {
					collectionInFlight.delete(key);
				});
				collectionInFlight.set(key, promise);
				return promise
			};
		},
	}
}

/**
 * Logs sub-resource plugin for createCrudStore.
 *
 * Many apps expose a logs collection keyed off the parent resource ID, via a
 * flat endpoint like `/sources/logs?source_id=<id>`. This plugin generates the
 * standard state, getters, and actions for that pattern so consumer stores
 * don't have to re-implement the same fetch/refresh logic.
 *
 * **Contributed state**
 * - `logs` — last fetched response (raw array or `{ results, ... }` shape)
 * - `logsLoading` — per-store loading flag
 * - `logsError` — last error (`ApiError` or null)
 *
 * **Contributed getters**
 * - `getLogs`, `isLogsLoading`, `getLogsError`
 *
 * **Contributed actions**
 * - `refreshLogs(filters?)` — fetch and store; returns `{ response, data }`
 * - `setLogs(data)` — replace state directly
 * - `clearLogs()` — reset to empty
 *
 * When `autoRefreshOnItemChange: true`, the plugin registers a
 * `store.$onAction` subscriber in its `setup` hook that observes `setItem`
 * and triggers `refreshLogs()` / `clearLogs()` after the action resolves.
 * This composes cleanly with other plugins that also want to observe
 * `setItem` — none of them have to override the action.
 *
 * **URL construction**
 * - `this._options.baseApiUrl + '/' + path` → e.g. `/sources/logs`
 * - Query params: `{ [parentIdParam]: item.id, ...defaultSort, ...filters }` —
 *   caller-supplied filters always win.
 *
 * @param {object} options Plugin options
 * @param {string} options.parentIdParam Required. Query param name carrying the
 *   parent resource's id — e.g. `'source_id'` for a sources store.
 * @param {string} [options.path] Path segment appended to the store's base API
 *   URL. Default: `'logs'`.
 * @param {object} [options.defaultSort] Default query params merged before
 *   user filters. Default: `{ '_sort[created]': 'desc' }`.
 * @param {boolean} [options.autoRefreshOnItemChange] When true, overrides
 *   `setItem` so selecting a new item automatically refreshes logs. Default:
 *   `false`.
 * @return {object} Plugin definition consumed by `createCrudStore`.
 *
 * @example
 * import { createCrudStore, logsPlugin } from '@conduction/nextcloud-vue'
 *
 * export const useSourceStore = createCrudStore('source', {
 *     endpoint: 'sources',
 *     entity: Source,
 *     plugins: [logsPlugin({ parentIdParam: 'source_id', autoRefreshOnItemChange: true })],
 * })
 *
 * // Later
 * const store = useSourceStore()
 * await store.refreshLogs({ '_limit': 50 })
 * console.log(store.logs, store.logsLoading)
 */
function logsPlugin(options = {}) {
	const {
		parentIdParam,
		path = 'logs',
		defaultSort = { '_sort[created]': 'desc' },
		autoRefreshOnItemChange = false,
	} = options;

	if (!parentIdParam) {
		throw new Error('logsPlugin: options.parentIdParam is required')
	}

	const actions = {
		/**
		 * Fetch logs for the current item from the logs endpoint.
		 *
		 * @param {object} [filters] Extra query params (override defaults).
		 * @return {Promise<{ response: Response, data: unknown }>}
		 */
		async refreshLogs(filters = {}) {
			this.logsLoading = true;
			this.logsError = null;

			try {
				const params = { ...defaultSort };
				if (!(parentIdParam in filters) && this.item?.id != null) {
					params[parentIdParam] = String(this.item.id);
				}
				Object.assign(params, filters);

				const url = this._options.baseApiUrl + '/' + path + buildQueryString(params);
				const response = await fetch(url, {
					method: 'GET',
					headers: buildHeaders(),
				});

				if (!response.ok) {
					this.logsError = await parseResponseError(response, 'logs');
					return { response, data: null }
				}

				const data = await response.json();
				this.logs = data;
				return { response, data }
			} catch (error) {
				this.logsError = error?.name === 'TypeError'
					? networkError(error)
					: genericError(error);
				throw error
			} finally {
				this.logsLoading = false;
			}
		},

		/**
		 * Replace the logs state directly (e.g. when a parent action returned
		 * logs as a side effect).
		 *
		 * @param {unknown} data Response data (array or `{ results, ... }`).
		 */
		setLogs(data) {
			this.logs = data;
		},

		/**
		 * Reset logs state back to empty defaults.
		 */
		clearLogs() {
			this.logs = [];
			this.logsLoading = false;
			this.logsError = null;
		},
	};

	const plugin = {
		name: 'logs',

		state: () => ({
			logs: [],
			logsLoading: false,
			logsError: null,
		}),

		getters: {
			getLogs: (state) => state.logs,
			isLogsLoading: (state) => state.logsLoading,
			getLogsError: (state) => state.logsError,
		},

		actions,
	};

	if (autoRefreshOnItemChange) {
		plugin.setup = function setup(store) {
			store.$onAction(({ name, after }) => {
				if (name !== 'setItem') return
				after(() => {
					if (store.item?.id != null) {
						store.refreshLogs().catch((error) => {
							console.error('logsPlugin: auto-refresh failed:', error);
						});
					} else {
						store.clearLogs();
					}
				});
			});
		};
	}

	return plugin
}

/**
 * Register mapping plugin for the object store.
 *
 * Adds state and actions for fetching OpenRegister registers and their
 * schemas, used by CnRegisterMapping to populate dropdowns.
 *
 * State: registers, registerSchemas, registersLoading, registersError
 * Actions: fetchRegisters, fetchSchemasForRegister, clearRegisterMapping
 * Getters: getRegisters, registerOptions, schemaOptions, isRegistersLoading, getRegistersError
 *
 * @return {Function} Plugin factory
 *
 * @example
 * const useStore = createObjectStore('object', {
 *   plugins: [registerMappingPlugin()],
 * })
 * const store = useStore()
 * await store.fetchRegisters()
 * const options = store.registerOptions       // [{ label, value }]
 * const schemas = store.schemaOptions('5')    // [{ label, value }]
 */
function registerMappingPlugin() {
	return {
		name: 'RegisterMapping',

		state: () => ({
			/** @type {Array} All available registers from OpenRegister */
			registers: [],
			/** @type {{[key: string]: Array}} Schemas keyed by register ID */
			registerSchemas: {},
			/** @type {boolean} Whether registers are being fetched */
			registersLoading: false,
			/** @type {string|null} Error message from last fetch */
			registersError: null,
		}),

		getters: {
			/**
			 * @param {object} state - Pinia state
			 * @return {Array} Raw register list
			 */
			getRegisters: (state) => state.registers,

			/**
			 * @param {object} state - Pinia state
			 * @return {boolean} Whether registers are loading
			 */
			isRegistersLoading: (state) => state.registersLoading,

			/**
			 * @param {object} state - Pinia state
			 * @return {string|null} Last error
			 */
			getRegistersError: (state) => state.registersError,

			/**
			 * Registers as NcSelect-compatible options.
			 *
			 * @param {object} state - Pinia state
			 * @return {Array<{label: string, value: string}>}
			 */
			registerOptions: (state) => state.registers.map((r) => ({
				label: r.title || r.slug || `Register ${r.id}`,
				value: String(r.id),
			})),
		},

		actions: {
			/**
			 * Get schemas for a register as NcSelect options.
			 *
			 * @param {string|number} registerId Register ID
			 * @return {Array<{label: string, value: string}>}
			 */
			schemaOptions(registerId) {
				const id = String(registerId);
				return (this.registerSchemas[id] || []).map((s) => ({
					label: s.title || s.slug || `Schema ${s.id}`,
					value: String(s.id),
				}))
			},

			/**
			 * Fetch all registers from OpenRegister with expanded schemas.
			 *
			 * @param {boolean} [withSchemas] Include schemas in response
			 * @return {Promise<Array>} Fetched registers
			 */
			async fetchRegisters(withSchemas = true) {
				this.registersLoading = true;
				this.registersError = null;

				try {
					let url = prefixUrl('/apps/openregister/api/registers');
					if (withSchemas) {
						url += '?_extend[]=schemas';
					}

					const response = await fetch(url, {
						method: 'GET',
						headers: buildHeaders(),
					});

					if (!response.ok) {
						this.registersError = `Failed to fetch registers: ${response.statusText}`;
						return []
					}

					const data = await response.json();
					const results = data.results || data;
					this.registers = Array.isArray(results) ? results : [];

					// Cache expanded schemas by register ID
					if (withSchemas) {
						for (const reg of this.registers) {
							if (Array.isArray(reg.schemas) && reg.schemas.length > 0) {
								this.registerSchemas = {
									...this.registerSchemas,
									[String(reg.id)]: reg.schemas.filter(
										(s) => s && typeof s === 'object' && s.id,
									),
								};
							}
						}
					}

					return this.registers
				} catch (error) {
					this.registersError = error.message || 'Network error fetching registers';
					return []
				} finally {
					this.registersLoading = false;
				}
			},

			/**
			 * Fetch schemas for a specific register.
			 * Returns cached data if already fetched via expanded registers.
			 *
			 * @param {string|number} registerId Register ID
			 * @return {Promise<Array>} Schemas for the register
			 */
			async fetchSchemasForRegister(registerId) {
				const id = String(registerId);

				// Return cached if available and non-empty
				if (this.registerSchemas[id]?.length > 0) {
					return this.registerSchemas[id]
				}

				// Check registers array for expanded schemas
				const register = this.registers.find((r) => String(r.id) === id);
				if (register?.schemas?.length > 0) {
					const schemas = register.schemas.filter(
						(s) => s && typeof s === 'object' && s.id,
					);
					if (schemas.length > 0) {
						this.registerSchemas = { ...this.registerSchemas, [id]: schemas };
						return schemas
					}
				}

				// Fetch from API as fallback
				try {
					const response = await fetch(
						prefixUrl(`/apps/openregister/api/registers/${id}?_extend[]=schemas`),
						{ method: 'GET', headers: buildHeaders() },
					);
					if (!response.ok) return []

					const data = await response.json();
					const schemas = (data.schemas || []).filter(
						(s) => s && typeof s === 'object' && s.id,
					);
					this.registerSchemas = { ...this.registerSchemas, [id]: schemas };
					return schemas
				} catch {
					return []
				}
			},

			/**
			 * Clear all register mapping state.
			 */
			clearRegisterMapping() {
				this.registers = [];
				this.registerSchemas = {};
				this.registersLoading = false;
				this.registersError = null;
			},
		},
	}
}

/**
 * Selection plugin for the object store.
 *
 * Adds selection management across all object types: select individual
 * objects by ID, check whether an entire collection is selected, and
 * toggle all-selected in one call.
 *
 * State added:
 *   - `selectedObjects` — Array of selected object IDs (strings)
 *
 * Getters added:
 *   - `isAllSelected(type)` — true when every object in the collection is selected
 *
 * Actions added:
 *   - `setSelectedObjects(ids)` — replace selection with an array of IDs
 *   - `clearSelectedObjects()` — deselect everything
 *   - `toggleSelectAllObjects(type)` — toggle between all-selected and none-selected
 *
 * @example
 * import { createObjectStore, selectionPlugin } from '@conduction/nextcloud-vue'
 *
 * const useMyStore = createObjectStore('myapp', {
 *   plugins: [selectionPlugin()],
 * })
 *
 * const store = useMyStore()
 * store.setSelectedObjects(['abc', 'def'])
 * store.toggleSelectAllObjects('invoice')
 * console.log(store.isAllSelected('invoice')) // true | false
 *
 * @return {object} Plugin definition
 */
function selectionPlugin() {
	return {
		name: 'selection',

		state: () => ({
			/**
			 * IDs of currently selected objects.
			 * @type {string[]}
			 */
			selectedObjects: [],
		}),

		getters: {
			/**
			 * Check if all objects in a type's collection are selected.
			 * Returns false when the collection is empty.
			 *
			 * @param {object} state pinia injected state
			 *
			 * @return {Function} (type: string) => boolean
			 */
			isAllSelected: (state) => (type) => {
				const collection = state.collections?.[type] || [];
				if (!collection.length) return false
				return collection.every((r) => {
					const id = r.id ?? r['@self']?.id;
					return id != null && state.selectedObjects.includes(id)
				})
			},
		},

		actions: {
			/**
			 * Replace the selection with the given array of IDs.
			 *
			 * @param {string[]} ids Object IDs to select
			 */
			setSelectedObjects(ids) {
				this.selectedObjects = Array.isArray(ids) ? ids : [];
			},

			/**
			 * Clear all selected objects.
			 */
			clearSelectedObjects() {
				this.selectedObjects = [];
			},

			/**
			 * Toggle selection of all objects in a type's collection.
			 * If all objects are already selected the selection is cleared;
			 * otherwise every object in the collection is selected.
			 *
			 * @param {string} type The registered type slug
			 */
			toggleSelectAllObjects(type) {
				const collection = this.getCollection(type);
				const ids = collection.map((r) => r.id ?? r['@self']?.id).filter(Boolean);
				if (this.isAllSelected(type)) {
					// Remove only this type's IDs, keep other types' selections
					const idsSet = new Set(ids);
					this.selectedObjects = this.selectedObjects.filter((id) => !idsSet.has(id));
				} else {
					// Add this type's IDs to existing selection (deduplicated)
					const existing = new Set(this.selectedObjects);
					for (const id of ids) existing.add(id);
					this.selectedObjects = [...existing];
				}
			},
		},
	}
}

/**
 * The type slug used internally by the search plugin.
 * Consumers can import this constant to avoid hard-coding the string 'search'.
 *
 * @type {string}
 */
const SEARCH_TYPE = 'search';

/**
 * Build the API URL for fetching a register by ID.
 *
 * @param {string} registerId OpenRegister register ID
 * @return {string} Full API URL path
 */
function getRegisterApiUrl(registerId) {
	return prefixUrl(`/apps/openregister/api/registers/${registerId}`)
}

/**
 * Build the API URL for fetching a schema by ID.
 *
 * @param {string} schemaId OpenRegister schema ID
 * @return {string} Full API URL path
 */
function getSchemaApiUrl(schemaId) {
	return prefixUrl(`/apps/openregister/api/schemas/${schemaId}`)
}

/**
 * Search plugin for the object store.
 *
 * Adds a dedicated search context to the store: a separate collection, pagination,
 * loading state, schema, register, and facet cache — all scoped to the current
 * `searchParams`. Unlike the main type-keyed collections, the search collection is
 * a single slot that is refetched whenever `refetchSearchCollection` is called.
 *
 * The plugin owns two URL-builder helpers (`getRegisterApiUrl`, `getSchemaApiUrl`)
 * that are also exported at module level for use outside the store.
 *
 * State added:
 *   - `searchParams` — Query parameters for the current search (register, schema, filters, …)
 *   - `searchVisibleColumns` — Column keys visible in the search results table
 *
 * Getters added:
 *   - `searchCollection` — Array of search result objects
 *   - `searchPagination` — `{ total, page, pages, limit }` for the last fetch
 *   - `searchLoading` — `true` while a fetch is in progress
 *   - `searchSchema` — Schema object for the current search register/schema pair
 *   - `searchRegister` — Register object for the current search register/schema pair
 *   - `searchFacets` — Facet data in CnIndexSidebar-compatible format
 *
 * Actions added:
 *   - `setSearchParams(params)` — Update search params (clears stale schema/register cache)
 *   - `setSearchVisibleColumns(columns)` — Replace the visible columns list
 *   - `clearSearchCollection()` — Reset collection, pagination, and facets
 *   - `refetchSearchCollection()` — Fetch collection using current `searchParams`
 *
 * @example
 * import { createObjectStore, searchPlugin, SEARCH_TYPE } from '@conduction/nextcloud-vue'
 *
 * const useMyStore = createObjectStore('myapp', {
 *   plugins: [searchPlugin()],
 * })
 *
 * const store = useMyStore()
 *
 * // Set params and fetch
 * store.setSearchParams({ register: 'reg-1', schema: 'schema-1', _search: 'foo' })
 * await store.refetchSearchCollection()
 *
 * // Read results
 * console.log(store.searchCollection)   // [{ id: '…', … }, …]
 * console.log(store.searchPagination)   // { total: 42, page: 1, pages: 3, limit: 20 }
 * console.log(store.searchSchema)       // { title: '…', properties: { … } }
 *
 * // Clear
 * store.clearSearchCollection()
 *
 * @return {object} Plugin definition
 */
function searchPlugin() {
	return {
		name: 'search',

		state: () => ({
			/**
			 * Query parameters for the active search.
			 * Must include `register` and `schema` for `refetchSearchCollection` to work.
			 * All other keys are forwarded as query-string parameters (e.g. `_search`, `_page`).
			 * @type {object}
			 */
			searchParams: {},

			/**
			 * Column keys that are visible in the search results table.
			 * @type {string[]}
			 */
			searchVisibleColumns: [],

			/** @private */
			_searchCollection: [],

			/** @private */
			_searchPagination: { total: 0, page: 1, pages: 1, limit: 20 },

			/** @private */
			_searchLoading: false,

			/** @private */
			_searchSchema: null,

			/** @private */
			_searchRegister: null,

			/** @private */
			_searchFacets: {},

			/** @private */
			_searchRequestId: 0,
		}),

		getters: {
			/**
			 * The current search result objects.
			 * @param {object} state Pinia state
			 * @return {Array}
			 */
			searchCollection: (state) => state._searchCollection,

			/**
			 * Pagination state for the last search fetch.
			 * @param {object} state Pinia state
			 * @return {{ total: number, page: number, pages: number, limit: number }}
			 */
			searchPagination: (state) => state._searchPagination,

			/**
			 * True while a search fetch is in progress.
			 * @param {object} state Pinia state
			 * @return {boolean}
			 */
			searchLoading: (state) => state._searchLoading,

			/**
			 * The schema object for the current search register/schema pair.
			 * Populated automatically by `refetchSearchCollection`.
			 * @param {object} state Pinia state
			 * @return {object|null}
			 */
			searchSchema: (state) => state._searchSchema,

			/**
			 * The register object for the current search register/schema pair.
			 * Populated automatically by `refetchSearchCollection`.
			 * @param {object} state Pinia state
			 * @return {object|null}
			 */
			searchRegister: (state) => state._searchRegister,

			/**
			 * Facet data from the last search fetch, in CnIndexSidebar-compatible format:
			 * `{ fieldName: { values: [{ value, count }] } }`.
			 * @param {object} state Pinia state
			 * @return {object}
			 */
			searchFacets: (state) => state._searchFacets,
		},

		actions: {
			/**
			 * Update the search parameters.
			 * If `register` or `schema` changes, the cached register/schema objects are
			 * cleared so the next `refetchSearchCollection` re-fetches them.
			 *
			 * @param {object} params New search params. Must include `register` and `schema`.
			 */
			setSearchParams(params) {
				if (params.register !== this.searchParams.register) {
					this._searchRegister = null;
				}
				if (params.schema !== this.searchParams.schema) {
					this._searchSchema = null;
				}
				this.searchParams = { ...params };
			},

			/**
			 * Merge the given properties into the current search parameters.
			 * Only the provided keys are overwritten; all other keys remain unchanged.
			 * If `register` or `schema` changes, the cached register/schema objects are
			 * cleared so the next `refetchSearchCollection` re-fetches them.
			 *
			 * @param {object} params Partial search params to merge
			 */
			updateSearchParams(params) {
				if ('register' in params && params.register !== this.searchParams.register) {
					this._searchRegister = null;
				}
				if ('schema' in params && params.schema !== this.searchParams.schema) {
					this._searchSchema = null;
				}
				this.searchParams = { ...this.searchParams, ...params };
			},

			/**
			 * Replace the list of visible column keys for the search results table.
			 *
			 * @param {string[]} columns Column key array
			 */
			setSearchVisibleColumns(columns) {
				this.searchVisibleColumns = Array.isArray(columns) ? columns : [];
			},

			/**
			 * Clear the search collection, pagination, and facets.
			 * Does not reset `searchParams` or `searchVisibleColumns`.
			 */
			clearSearchCollection() {
				this._searchCollection = [];
				this._searchPagination = { total: 0, page: 1, pages: 1, limit: 20 };
				this._searchFacets = {};
			},

			/**
			 * Fetch the search collection using the current `searchParams`.
			 * `searchParams` must include `register` and `schema`; all other keys are
			 * forwarded as query-string parameters to the objects endpoint.
			 *
			 * Side-effects:
			 * - Fetches and caches `_searchSchema` and `_searchRegister` (non-blocking,
			 *   only when not already cached).
			 * - Updates `_searchCollection`, `_searchPagination`, and `_searchFacets`.
			 *
			 * @return {Promise<Array>} The fetched collection (empty array on error)
			 */
			async refetchSearchCollection() {
				const { register, schema, filters, ...queryParams } = this.searchParams;

				// Flatten the filters object into individual query params so the
				// backend receives them as field-level filters (e.g. ?title=foo)
				// instead of a single `filters=[object Object]` param.
				if (filters && typeof filters === 'object') {
					for (const [field, values] of Object.entries(filters)) {
						if (Array.isArray(values) && values.length > 0) {
							queryParams[field] = values;
						} else if (values && !Array.isArray(values)) {
							queryParams[field] = values;
						}
					}
				}

				if (!register || !schema) {
					console.warn('[searchPlugin] refetchSearchCollection called without register/schema in searchParams');
					return []
				}

				// Increment request counter to detect stale responses
				const requestId = ++this._searchRequestId;

				this._searchLoading = true;

				// Auto-register the type so saveObject/deleteObject work
				const type = this.createObjectTypeSlug(register, schema);
				if (type && !this.objectTypes.includes(type)) {
					this.registerObjectType(type, schema, register);
				}

				// Kick off schema/register fetches in parallel (non-blocking)
				if (!this._searchSchema) {
					this._fetchSearchSchema(schema);
				}
				if (!this._searchRegister) {
					this._fetchSearchRegister(register);
				}

				try {
					const baseUrl = this._options?.baseUrl || prefixUrl('/apps/openregister/api/objects');
					const url = `${baseUrl}/${register}/${schema}` + buildQueryString(queryParams);

					const response = await fetch(url, {
						method: 'GET',
						headers: buildHeaders(),
					});

					// A newer request was fired while this one was in-flight — discard
					if (requestId !== this._searchRequestId) {
						return []
					}

					if (!response.ok) {
						console.error('[searchPlugin] Failed to fetch search collection:', response.status);
						return []
					}

					const data = await response.json();

					// Re-check after JSON parsing (also async)
					if (requestId !== this._searchRequestId) {
						return []
					}

					const results = data.results || data;

					this._searchCollection = results;
					this._searchPagination = {
						total: data.total || results.length,
						page: data.page || 1,
						pages: data.pages || 1,
						limit: queryParams._limit || 20,
					};

					if (data.facets) {
						const transformed = {};
						for (const [key, facet] of Object.entries(data.facets)) {
							if (facet.buckets || facet.data?.buckets) {
								const buckets = facet.buckets || facet.data.buckets;
								transformed[key] = {
									values: buckets.map((b) => ({
										value: b.key ?? b.value,
										count: b.count || 0,
									})),
								};
							}
						}
						this._searchFacets = transformed;
					}

					return results
				} catch (error) {
					console.error('[searchPlugin] Error fetching search collection:', error);
					return []
				} finally {
					// Only clear loading if this is still the latest request
					if (requestId === this._searchRequestId) {
						this._searchLoading = false;
					}
				}
			},

			/**
			 * Fetch and cache the schema object for the given schema ID.
			 * Internal — called by `refetchSearchCollection`.
			 *
			 * @param {string} schemaId OpenRegister schema ID
			 * @return {Promise<void>}
			 */
			async _fetchSearchSchema(schemaId) {
				try {
					const response = await fetch(getSchemaApiUrl(schemaId), {
						method: 'GET',
						headers: buildHeaders(),
					});
					if (response.ok) {
						this._searchSchema = await response.json();
					}
				} catch {
					// Non-critical — searchSchema stays null
				}
			},

			/**
			 * Fetch and cache the register object for the given register ID.
			 * Internal — called by `refetchSearchCollection`.
			 *
			 * @param {string} registerId OpenRegister register ID
			 * @return {Promise<void>}
			 */
			async _fetchSearchRegister(registerId) {
				try {
					const response = await fetch(getRegisterApiUrl(registerId), {
						method: 'GET',
						headers: buildHeaders(),
					});
					if (response.ok) {
						this._searchRegister = await response.json();
					}
				} catch {
					// Non-critical — searchRegister stays null
				}
			},
		},
	}
}

/**
 * Composable for managing list view state with full objectStore integration.
 *
 * When called with an `objectType` string, connects to the objectStore and handles
 * schema loading, collection fetching, sidebar wiring, and all event handlers
 * automatically. Everything a `CnIndexPage`-based list view needs is returned
 * directly — no additional computed properties or methods required in the component.
 *
 * Backward-compatible: existing `useListView(options)` and `useListView()` calls
 * continue to work without modification.
 *
 * @param {string|object} [objectTypeOrOptions] Object type slug (new API) or legacy options object
 * @param {object} [options] Options (new API only)
 * @param {object|null} [options.objectStore] Custom object store instance (from createObjectStore). When provided, uses this store instead of the default useObjectStore(). Required when the app uses createObjectStore with a custom store ID.
 * @param {object|null} [options.sidebarState] Sidebar state object from `inject('sidebarState')`. When provided, the composable wires and unwires the sidebar automatically on mount/unmount.
 * @param {number} [options.defaultPageSize] Default `_limit` sent to the API
 * @param {number} [options.debounceMs] Search debounce in milliseconds
 * @param {object} [options.defaultSort] Default sort applied on mount e.g. `{ key: 'createdAt', order: 'desc' }`
 * @param {object|Function} [options.fixedFilters] A filter map (or getter returning one) merged into every fetch AFTER the user's facet filters, so the fixed entries always win. Used e.g. by `CnIndexPage` to apply a route-param-scoped `pages[].config.filter`. Default `{}` — omitting it is behaviourally identical to before.
 * @return {object} Reactive state and event handlers
 *
 * @example
 * // New API — minimal
 * const { schema, objects, loading, pagination,
 *         onSearch, onSort, onFilterChange, onPageChange, refresh } = useListView('client')
 *
 * @example
 * // New API — with sidebar wiring
 * const list = useListView('client', {
 *   sidebarState: inject('sidebarState', null),
 * })
 *
 * @example
 * // Legacy API — still works
 * const { searchTerm, filters, onSearchInput, toggleSort } = useListView({
 *   objectType: 'client',
 *   fetchFn: (type, params) => objectStore.fetchCollection(type, params),
 * })
 */
function useListView(objectTypeOrOptions, options) {
	// Backward compat: if first arg is an object or absent, delegate to legacy implementation
	if (!objectTypeOrOptions || typeof objectTypeOrOptions === 'object') {
		return useLegacyListView(objectTypeOrOptions || {})
	}

	// ── New API ──────────────────────────────────────────────────────────
	const objectType = objectTypeOrOptions;
	const opts = options || {};
	const sidebarState = opts.sidebarState || null;

	const objectStore = opts.objectStore || useObjectStore();

	// ── State refs ───────────────────────────────────────────────────────
	const schema = Vue.ref(null);
	const searchTerm = Vue.ref('');
	const sortKey = Vue.ref(opts.defaultSort?.key || null);
	const sortOrder = Vue.ref(opts.defaultSort?.order || 'asc');
	const activeFilters = Vue.ref({});
	const visibleColumns = Vue.ref(null);
	const pageSize = Vue.ref(opts.defaultPageSize || 20);

	// ── Computed refs from the store ─────────────────────────────────────
	const objects = Vue.computed(() => objectStore.collections[objectType] || []);
	const loading = Vue.computed(() => objectStore.loading[objectType] || false);
	const pagination = Vue.computed(
		() => objectStore.pagination[objectType] || { total: 0, page: 1, pages: 1, limit: 20 },
	);

	let searchTimeout = null;

	// ── Param construction ───────────────────────────────────────────────

	/**
	 * Resolve `opts.fixedFilters` to a plain map. Accepts a plain object OR a
	 * function/getter returning one (so callers can derive it from reactive
	 * sources — e.g. route params — and have it re-read on every fetch).
	 *
	 * @return {object} The fixed-filter map (may be empty).
	 */
	function resolveFixedFilters() {
		const f = typeof opts.fixedFilters === 'function' ? opts.fixedFilters() : opts.fixedFilters;
		return (f && typeof f === 'object') ? f : {}
	}

	/**
	 * Build API fetch params from current reactive state.
	 *
	 * @param {number} page Page number to request
	 * @return {object} Params object ready to pass to fetchCollection
	 */
	function buildParams(page) {
		const params = { _limit: pageSize.value, _page: page };

		if (searchTerm.value) {
			params._search = searchTerm.value;
		}

		if (sortKey.value) {
			params._order = { [sortKey.value]: sortOrder.value };
		}

		for (const [key, values] of Object.entries(activeFilters.value)) {
			if (values && values.length > 0) {
				// Single-value arrays are unwrapped to scalar params
				params[key] = values.length === 1 ? values[0] : values;
			}
		}

		// Fixed filters (e.g. a route-param-scoped `pages[].config.filter`) are
		// merged LAST so they always win over a colliding facet `activeFilter`.
		for (const [key, value] of Object.entries(resolveFixedFilters())) {
			if (value !== undefined && value !== null && value !== '') {
				params[key] = value;
			}
		}

		return params
	}

	// ── Fetch ────────────────────────────────────────────────────────────

	/**
	 * Fetch the collection using current state params and update sidebar facet data.
	 *
	 * @param {number} [page] Page to fetch
	 * @return {Promise<void>}
	 */
	async function refresh(page = 1) {
		await objectStore.fetchCollection(objectType, buildParams(page));
	}

	// ── Event handlers ───────────────────────────────────────────────────

	/**
	 * Handle search input. Debounced by `options.debounceMs` (default 300 ms).
	 *
	 * @param {string} value New search string
	 */
	function onSearch(value) {
		searchTerm.value = value;
		clearTimeout(searchTimeout);
		searchTimeout = setTimeout(() => refresh(1), opts.debounceMs || 300);
	}

	/**
	 * Handle sort change. Updates sort state and triggers refresh.
	 *
	 * @param {{key: string, order: string}} sort New sort definition
	 */
	function onSort({ key, order }) {
		sortKey.value = key;
		sortOrder.value = order || 'asc';
		refresh(1);
	}

	/**
	 * Handle filter change for a single key. Empty arrays remove the key.
	 *
	 * @param {string} key Filter key (maps to API param name)
	 * @param {Array} values Selected filter values
	 */
	function onFilterChange(key, values) {
		if (!values || values.length === 0) {
			const updated = { ...activeFilters.value };
			delete updated[key];
			activeFilters.value = updated;
		} else {
			activeFilters.value = { ...activeFilters.value, [key]: values };
		}
		refresh(1);
	}

	/**
	 * Handle page navigation.
	 *
	 * @param {number} page Page number to navigate to
	 */
	function onPageChange(page) {
		refresh(page);
	}

	/**
	 * Handle page-size change. Resets to page 1.
	 *
	 * @param {number} size New page size
	 */
	function onPageSizeChange(size) {
		pageSize.value = size;
		refresh(1);
	}

	// ── Sidebar wiring ───────────────────────────────────────────────────

	function setupSidebar() {
		if (!sidebarState) return
		sidebarState.active = true;
		sidebarState.schema = schema.value;
		sidebarState.searchValue = searchTerm.value;
		sidebarState.activeFilters = {};
		sidebarState.onSearch = onSearch;
		sidebarState.onColumnsChange = (cols) => {
			visibleColumns.value = cols;
		};
		sidebarState.onFilterChange = ({ key, values }) => onFilterChange(key, values);
	}

	function teardownSidebar() {
		if (!sidebarState) return
		sidebarState.active = false;
		sidebarState.schema = null;
		sidebarState.activeFilters = {};
		sidebarState.facetData = {};
		sidebarState.onSearch = null;
		sidebarState.onColumnsChange = null;
		sidebarState.onFilterChange = null;
	}

	// Push facet data to sidebar after each store update
	if (sidebarState) {
		Vue.watch(
			() => objectStore.facets[objectType],
			(facets) => {
				sidebarState.facetData = facets || {};
			},
		);
	}

	// ── Lifecycle ────────────────────────────────────────────────────────

	Vue.onMounted(async () => {
		schema.value = await objectStore.fetchSchema(objectType);
		if (sidebarState) {
			setupSidebar();
		}
		await refresh(1);
	});

	Vue.onBeforeUnmount(() => {
		clearTimeout(searchTimeout);
		teardownSidebar();
	});

	// ── Return value ─────────────────────────────────────────────────────

	return {
		// Store-derived
		schema,
		objects,
		loading,
		pagination,
		// Local state
		searchTerm,
		sortKey,
		sortOrder,
		activeFilters,
		visibleColumns,
		pageSize,
		// Event handlers
		onSearch,
		onSort,
		onFilterChange,
		onPageChange,
		onPageSizeChange,
		// Explicit fetch
		refresh,
	}
}

// ── Legacy implementation ─────────────────────────────────────────────────────

/**
 * Legacy `useListView(options)` implementation.
 * Preserved verbatim for backward compatibility.
 *
 * @param {object} options Legacy options object
 * @param {string} [options.objectType] The registered object type slug
 * @param {Function} [options.fetchFn] Function to call: (type, params) => Promise<Array>
 * @param {number} [options.debounceMs] Search debounce in milliseconds
 * @param {number} [options.pageSize] Default page size
 * @param {object} [options.defaultSort] Default sort: { key: string, order: 'asc'|'desc' }
 * @return {object} Reactive state and methods
 */
function useLegacyListView(options) {
	const searchTerm = Vue.ref('');
	const filters = Vue.ref({});
	const sortKey = Vue.ref(options.defaultSort?.key || null);
	const sortOrder = Vue.ref(options.defaultSort?.order || 'asc');
	const currentPage = Vue.ref(1);
	const pageSize = Vue.ref(options.pageSize || 20);

	let searchTimeout = null;

	function buildFetchParams() {
		const params = {
			_limit: pageSize.value,
			_page: currentPage.value,
		};

		if (searchTerm.value) {
			params._search = searchTerm.value;
		}

		if (sortKey.value) {
			params._order = { [sortKey.value]: sortOrder.value };
		}

		for (const [key, value] of Object.entries(filters.value)) {
			if (value !== null && value !== '' && value !== false) {
				params[key] = value;
			}
		}

		return params
	}

	async function fetchData(page) {
		if (page !== undefined) {
			currentPage.value = page;
		}
		const params = buildFetchParams();
		if (options.fetchFn) {
			return options.fetchFn(options.objectType, params)
		}
	}

	function onSearchInput(value) {
		searchTerm.value = value;
		clearTimeout(searchTimeout);
		searchTimeout = setTimeout(() => fetchData(1), options.debounceMs || 300);
	}

	function toggleSort(key) {
		if (sortKey.value === key) {
			if (sortOrder.value === 'asc') {
				sortOrder.value = 'desc';
			} else {
				sortKey.value = null;
				sortOrder.value = 'asc';
			}
		} else {
			sortKey.value = key;
			sortOrder.value = 'asc';
		}
		fetchData(1);
	}

	function setFilter(key, value) {
		filters.value = { ...filters.value, [key]: value };
		fetchData(1);
	}

	function clearAllFilters() {
		searchTerm.value = '';
		filters.value = {};
		sortKey.value = options.defaultSort?.key || null;
		sortOrder.value = options.defaultSort?.order || 'asc';
		fetchData(1);
	}

	function goToPage(page) {
		currentPage.value = page;
		fetchData();
	}

	Vue.onBeforeUnmount(() => clearTimeout(searchTimeout));

	return {
		searchTerm,
		filters,
		sortKey,
		sortOrder,
		currentPage,
		pageSize,
		onSearchInput,
		toggleSort,
		setFilter,
		clearAllFilters,
		goToPage,
		fetch: fetchData,
		buildFetchParams,
	}
}

/**
 * Composable for managing detail view state with full objectStore integration.
 *
 * When called with `objectType` and `id`, connects to the objectStore and handles
 * fetching on mount, re-fetching on `id` changes, save/delete operations, and
 * optional router navigation — eliminating boilerplate from every detail-view component.
 *
 * Backward-compatible: existing `useDetailView(options)` and `useDetailView()` calls
 * continue to work without modification.
 *
 * @param {string|object} [objectTypeOrOptions] Object type slug (new API) or legacy options object
 * @param {string|import('vue').Ref<string>} [id] Object ID or `'new'` for a new object
 * @param {object} [options] Options (new API only)
 * @param {Function} [options.objectStore] Custom object store instance (from createObjectStore)
 * @param {object|null} [options.router] Vue Router instance — enables post-save/delete navigation
 * @param {string|null} [options.listRouteName] Route name to navigate to after successful delete
 * @param {string|null} [options.detailRouteName] Route name to navigate to after successful create
 * @param {string} [options.nameField] Field shown in error messages
 * @return {object} Reactive state and operation functions
 *
 * @example
 * // New API
 * const { object, isNew, loading, saving, editing,
 *         onSave, confirmDelete, showDeleteDialog } = useDetailView('client', props.id, {
 *   router: useRouter(),
 *   listRouteName: 'ClientList',
 *   detailRouteName: 'ClientDetail',
 * })
 *
 * @example
 * // Legacy API — still works
 * const { objectData, editing, load, save, confirmDelete } = useDetailView({
 *   objectType: 'client',
 *   fetchFn: (type, id) => objectStore.fetchObject(type, id),
 *   saveFn: (type, data) => objectStore.saveObject(type, data),
 *   deleteFn: (type, id) => objectStore.deleteObject(type, id),
 * })
 */
function useDetailView(objectTypeOrOptions, id, options) {
	// Backward compat: if first arg is an object or absent, delegate to legacy implementation
	if (!objectTypeOrOptions || typeof objectTypeOrOptions === 'object') {
		return useLegacyDetailView(objectTypeOrOptions || {})
	}

	// ── New API ──────────────────────────────────────────────────────────
	const objectType = objectTypeOrOptions;
	const opts = options || {};
	const router = opts.router || null;
	const listRouteName = opts.listRouteName || null;
	const detailRouteName = opts.detailRouteName || null;

	// Normalise `id` to a ref so we can watch it
	const idRef = Vue.isRef(id) ? id : Vue.ref(id);

	const objectStore = opts.objectStore ? opts.objectStore() : useObjectStore();

	// ── State refs ───────────────────────────────────────────────────────
	const editing = Vue.ref(false);
	const saving = Vue.ref(false);
	const showDeleteDialog = Vue.ref(false);
	const error = Vue.ref(null);
	const validationErrors = Vue.ref(null);

	// ── Computed refs from the store ─────────────────────────────────────

	const isNew = Vue.computed(() => !idRef.value || idRef.value === 'new');

	const object = Vue.computed(() => {
		if (isNew.value) return {}
		return objectStore.getObject(objectType, idRef.value) || {}
	});

	const loading = Vue.computed(() => objectStore.loading[objectType] || false);

	// ── Operations ───────────────────────────────────────────────────────

	/**
	 * Save the object. Handles create (POST) and update (PUT) branches.
	 * On 422 validation error the `validationErrors` ref is populated.
	 * On successful create with `detailRouteName` set, the router navigates to the detail route.
	 * On successful update, `editing` is set to false and the object is re-fetched.
	 *
	 * @param {object} formData Data to save
	 * @return {Promise<object|null>} Saved object or null on error
	 */
	async function onSave(formData) {
		saving.value = true;
		error.value = null;
		validationErrors.value = null;

		try {
			const dataToSave = isNew.value ? formData : { ...formData, id: idRef.value };
			const result = await objectStore.saveObject(objectType, dataToSave);

			if (!result) {
				// Store already set error; surface it
				error.value = objectStore.errors[objectType]?.message || 'Failed to save';
				return null
			}

			if (isNew.value && router && detailRouteName) {
				router.push({ name: detailRouteName, params: { id: result.id } });
			} else {
				editing.value = false;
				await objectStore.fetchObject(objectType, idRef.value);
			}

			return result
		} catch (err) {
			if (err?.response?.status === 422 || err?.status === 422) {
				const data = err?.response?.data || err?.data || {};
				validationErrors.value = data.errors || data;
			} else {
				error.value = err.message || 'Failed to save';
			}
			return null
		} finally {
			saving.value = false;
		}
	}

	/**
	 * Delete the current object. On success, navigate to `listRouteName` if configured.
	 * On failure, `error` ref is set.
	 *
	 * @return {Promise<boolean>} True if deleted successfully
	 */
	async function confirmDelete() {
		error.value = null;
		try {
			const success = await objectStore.deleteObject(objectType, idRef.value);
			if (success) {
				showDeleteDialog.value = false;
				if (router && listRouteName) {
					router.push({ name: listRouteName });
				}
			} else {
				error.value = objectStore.errors[objectType]?.message || 'Failed to delete';
			}
			return success
		} catch (err) {
			error.value = err.message || 'Failed to delete';
			return false
		}
	}

	// ── Lifecycle ────────────────────────────────────────────────────────

	async function fetchIfNeeded(currentId) {
		if (!currentId || currentId === 'new') return
		await objectStore.fetchObject(objectType, currentId);
	}

	Vue.onMounted(() => {
		fetchIfNeeded(idRef.value);
	});

	Vue.watch(idRef, (newId) => {
		fetchIfNeeded(newId);
	});

	// ── Return value ─────────────────────────────────────────────────────

	return {
		// Store-derived
		object,
		loading,
		// Computed state
		isNew,
		// Local state
		editing,
		saving,
		showDeleteDialog,
		error,
		validationErrors,
		// Operations
		onSave,
		confirmDelete,
	}
}

// ── Legacy implementation ─────────────────────────────────────────────────────

/**
 * Legacy `useDetailView(options)` implementation.
 * Preserved verbatim for backward compatibility.
 *
 * @param {object} options Legacy options object
 * @param {string} [options.objectType] The registered object type slug
 * @param {Function} [options.fetchFn] (type, id) => Promise<object>
 * @param {Function} [options.saveFn] (type, data) => Promise<object>
 * @param {Function} [options.deleteFn] (type, id) => Promise<boolean>
 * @param {Function} [options.onSaved] Callback after successful save
 * @param {Function} [options.onDeleted] Callback after successful delete
 * @return {object} Reactive state and methods
 */
function useLegacyDetailView(options) {
	const objectData = Vue.ref({});
	const editing = Vue.ref(false);
	const loading = Vue.ref(false);
	const saving = Vue.ref(false);
	const showDeleteDialog = Vue.ref(false);
	const error = Vue.ref(null);

	async function load(id) {
		loading.value = true;
		error.value = null;
		try {
			const result = options.fetchFn
				? await options.fetchFn(options.objectType, id)
				: null;
			if (result) {
				objectData.value = { ...result };
			}
			return result
		} catch (err) {
			error.value = err.message || 'Failed to load';
			return null
		} finally {
			loading.value = false;
		}
	}

	async function save(formData) {
		saving.value = true;
		error.value = null;
		try {
			const data = formData || objectData.value;
			const result = options.saveFn
				? await options.saveFn(options.objectType, data)
				: null;
			if (result) {
				objectData.value = { ...result };
				editing.value = false;
				if (options.onSaved) {
					options.onSaved(result);
				}
			}
			return result
		} catch (err) {
			error.value = err.message || 'Failed to save';
			return null
		} finally {
			saving.value = false;
		}
	}

	function confirmDelete() {
		showDeleteDialog.value = true;
	}

	async function executeDelete(id) {
		const deleteId = id || objectData.value.id;
		loading.value = true;
		error.value = null;
		try {
			const success = options.deleteFn
				? await options.deleteFn(options.objectType, deleteId)
				: false;
			if (success) {
				showDeleteDialog.value = false;
				if (options.onDeleted) {
					options.onDeleted();
				}
			}
			return success
		} catch (err) {
			error.value = err.message || 'Failed to delete';
			return false
		} finally {
			loading.value = false;
		}
	}

	return {
		objectData,
		editing,
		loading,
		saving,
		showDeleteDialog,
		error,
		load,
		save,
		confirmDelete,
		executeDelete,
	}
}

/**
 * Standalone composable for fetching sub-resources outside the Pinia store.
 *
 * Use this for app-specific sub-resources that don't follow the standard
 * OpenRegister pattern or don't need shared state (e.g. CalDAV tasks,
 * ICommentsManager notes). State is scoped to the component lifecycle.
 *
 * For sub-resources that need shared state across components, use store
 * plugins (filesPlugin, auditTrailsPlugin, etc.) instead.
 *
 * @param {object} store The object store instance (must have objectTypeRegistry and _options)
 * @param {string} endpoint URL path segment appended to the object URL (e.g. 'tasks')
 * @param {object} [options] Composable options
 * @param {Function} [options.transform] Transform function applied to each result item
 * @param {number} [options.limit] Default page size
 * @return {object} Reactive state and methods
 *
 * @example
 * // Basic usage
 * const tasks = useSubResource(store, 'tasks')
 * await tasks.fetch('case', caseId)
 * console.log(tasks.data.results)
 *
 * @example
 * // With transform function (e.g. CalDAV task normalization)
 * const tasks = useSubResource(store, 'tasks', {
 *   transform: (task) => ({
 *     id: task.uid || task.id,
 *     title: task.summary,
 *     deadline: task.due,
 *     status: task.status,
 *   }),
 * })
 */
